def transform(grid):
    h,w=len(grid),len(grid[0])
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                y,x=stack.pop(); pts.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0=min(y for y,x in pts); x0=min(x for y,x in pts)
            bh=max(y for y,x in pts)-y0+1; bw=max(x for y,x in pts)-x0+1
            mask={(y-y0,x-x0) for y,x in pts}
            comps.append((color,y0,x0,bh,bw,mask))
    out=[[0]*w for _ in range(h)]
    # Each object's template is completed from all same-sized pieces; the arrangement is packed at the top.
    groups={}
    for q in comps: groups.setdefault((q[3],q[4]),[]).append(q)
    for (bh,bw),items in groups.items():
        union=set().union(*(q[5] for q in items))
        for color,y0,x0,_,_,_ in items:
            for dy,dx in union:
                if y0+dy<h and x0+dx<w: out[y0+dy][x0+dx]=color
    return out
PY

