        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); stack.append((yy,xx))
        objs.append((min(y for y,x in cells), color, cells))
    out=[row[:] for row in grid]
    # The distinctive color-2 silhouette is the stencil: other objects occupy its shape's holes.
    reference=next((o for o in objs if o[1]==2), None)
    if reference is None: return out
    ry, _, rcells=reference
    rcols={x for y,x in rcells if y==ry}
    # Translate each other motif so its top edge aligns with the reference top edge,
    # preserving existing colors and adding the translated full motif.
    for y0,color,cells in objs:
      if color==2: continue
      dy=ry-y0
      for y,x in cells:
        if 0<=y+dy<h: out[y+dy][x]=color
    return out

