def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); stack.append((yy,xx))
        y0=min(y for y,x in cells); x0=min(x for y,x in cells)
        mask={(y-y0,x-x0) for y,x in cells}
        objs.append((y0,x0,color,mask))
    # Each irregular repeated shape is a stencil; top-align all stencils and overlay them.
    top=min(o[0] for o in objs)
    out=[[0]*w for _ in range(h)]
    for y0,x0,color,mask in objs:
      for dy,dx in mask:
        y=top+dy
        if y<h and x0+dx<w: out[y][x0+dx]=color
    return out
