def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if not v or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
              seen.add((yy,xx)); stack.append((yy,xx))
        y0=min(y for y,x in cells); x0=min(x for y,x in cells)
        mask={(y-y0,x-x0) for y,x in cells}
        comps.append((v,y0,x0,mask))
    # All pieces share one motif, split vertically. Move each to the common upper baseline,
